//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd; // 법인조회
scwin.gAcptNo;
scwin.gViewerStat = 'P';
scwin.pageSize = 10; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vScrenID = 'ULDSTF26500.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    $c.stf.Combo_CBDataSet(cmb_PerPage);
    dts_FormUpclss.DataID = "/CodeAction.do?method=listFormUpclss&For=R";
    dts_FormUpclss.Reset();

    //회사속성 콤보박스 초기화
    dts_COMPANY_ATTRIBUTE.DataID = "/CodeAction.do?method=listCompanyAttribute&For=R";
    dts_COMPANY_ATTRIBUTE.Reset();
};


// session 값을 control 에 binding 시키는 함수.
scwin.initPage = function() {
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    // 전년 1년 기본값.
    var myDate = new Date();
    var curr_yyyy = myDate.getYear();
    var prev_yyyy = curr_yyyy - 1;
    $c.stf.setObjectValue(edt_EDATE, $c.ut.cGetToday2());
    $c.stf.setObjectValue(edt_SDATE, $c.ut.cGetToday2());
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (scwin.gLdMktTp == "9") {

    } else {
        rdo_MKT_ID.setDisabled(true);
    }
    // alert(gLdMktTp);
    rdo_DISCLS_TYPE.setValue('1');
    cmb_DISCLS_RSN_CLSS.setDisabled(true);
    scwin.fn_getClassByUpClass();
};
scwin.fn_getClassByUpClass = function() {
    var vUPCLSS = $c.stf.getObjectValue(cmb_UPCLSS);

    // 공시사유
    var url = "/CodeAction.do?method=listDisclsRsnclssEx&UPCLSS=" + vUPCLSS + "&For=R";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
    dts_DISCLS_RSN_CLSS.DataID = url;
    dts_DISCLS_RSN_CLSS.Reset();

    // 공시유형
    url = "/CodeAction.do?method=listDisclsTpclss&UPCLSS=" + vUPCLSS + "&For=R";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
    dts_DISCLS_TP_CLSS.DataID = url;
    dts_DISCLS_TP_CLSS.Reset();
    return;
    if (vUPCLSS == "") {
        // 전체

    } else {
        // 공시사유
        var url = "/CodeAction.do?method=listDisclsRsnclss&inputMessageId=FORMUPCLSS_IN&outputMessageId=CODE_OUT" + "&FOR=C&FORMUPCLSSCD=" + vUPCLSS;
        dts_DISCLS_RSN_CLSS.DataID = url;
        dts_DISCLS_RSN_CLSS.Reset();

        // 공시유형
        url = "/CodeAction.do?method=listDisclsTpclss&UPCLSS=" + vUPCLSS + "&For=C";
        dts_DISCLS_TP_CLSS.DataID = url;
        dts_DISCLS_TP_CLSS.Reset();
    }
};
scwin.fn_SetCtrlByMktId = function() {
    // 코스닥은 공시유형이 없고 사유만 있음.

    /*
    	var i = getObjectValue(rdo_MKT_ID);
    	if (i == "2")
    	{// 코스닥.
    		setObjectValue(cmb_DISCLS_TP_CLSS, "");	
    		if (getObjectValue(rdo_FORM_CLASS) == "1")
    		{
    			alert("코스닥은 공시유형으로 검색할 수 없습니다.");
    			setObjectValue(rdo_FORM_CLASS, "2");			
    		}
    		cmb_DISCLS_TP_CLSS.Enable2 = false;
    		cmb_DISCLS_RSN_CLSS.Enable2 = true;
    	}
    	else
    	{
    		cmb_DISCLS_TP_CLSS.Enable2 = true;
    		cmb_DISCLS_RSN_CLSS.Enable2 = true;
    	}
    */
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    var argv = fn_Search.arguments;
    var argc = fn_Search.arguments.length;
    var vPAGENO = (argc == 0) ? 0 : vPAGENO = argv[0];
    var vSDATE = $c.stf.getObjectValue(edt_SDATE);
    var vEDATE = $c.stf.getObjectValue(edt_EDATE);
    if (vSDATE == "" || vEDATE == "") {
        $c.win.alert("[기간]을 선택하세요.");
        return; // 처리시각
    }
    var vF = $c.stf.getObjectValue(chb_F);
    var vM = $c.stf.getObjectValue(chb_M);
    var vA = $c.stf.getObjectValue(chb_A);
    var vU = $c.stf.getObjectValue(chb_U);
    if (vF == "N" && vM == "N" && vA == "N" && vU == "N") {
        $c.stf.setObjectValue(chb_F, "Y");
        $c.stf.setObjectValue(chb_M, "Y");
    }
    var url = "/DisclosureCountStatistics.do?method=listDisclosureStatistics";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&SDATE=" + vSDATE;
    url += "&EDATE=" + vEDATE;
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SUBMIT_F=" + $c.stf.getObjectValue(chb_F);
    url += "&SUBMIT_M=" + $c.stf.getObjectValue(chb_M);
    url += "&SUBMIT_A=" + $c.stf.getObjectValue(chb_A);
    url += "&SUBMIT_U=" + $c.stf.getObjectValue(chb_U);
    url += "&FORM_UPCLSS_CD=" + $c.stf.getObjectValue(cmb_UPCLSS);
    url += "&TP_CLSS_CD=" + $c.stf.getObjectValue(cmb_DISCLS_TP_CLSS);
    url += "&RSN_CLSS_CD=" + $c.stf.getObjectValue(cmb_DISCLS_RSN_CLSS);
    url += "&COM_TP_CD=" + $c.stf.getObjectValue(cmb_COMPANY_ATTRIBUTE);
    url += "&PAGENO=" + vPAGENO;
    url += "&PAGESIZE=" + $c.stf.getObjectValue(cmb_PerPage);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(url);
    dts_Grid.DataID = url;
    dts_Grid.Reset();
};
scwin.PageNoCall = function(vPageNo) {
    scwin.vCurrPageNo = vPageNo;
    scwin.fn_Search(vPageNo);
};
scwin.fn_ToExcel = function() {
    $c.cm.ShowWin(grd_Grid);
    var vSDATE = $c.stf.getObjectValue(edt_SDATE);
    var vEDATE = $c.stf.getObjectValue(edt_EDATE);
    if (vSDATE == "" || vEDATE == "") {
        $c.win.alert("[기간]을 선택하세요.");
        return; // 처리시각
    }
    var vF = $c.stf.getObjectValue(chb_F);
    var vM = $c.stf.getObjectValue(chb_M);
    var vA = $c.stf.getObjectValue(chb_A);
    var vU = $c.stf.getObjectValue(chb_U);
    if (vF == "N" && vM == "N" && vA == "N" && vU == "N") {
        $c.stf.setObjectValue(chb_F, "Y");
        $c.stf.setObjectValue(chb_M, "Y");
    }
    var url = "/DisclosureCountStatistics.do?method=listDisclosureStatistics";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&SDATE=" + vSDATE;
    url += "&EDATE=" + vEDATE;
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SUBMIT_F=" + $c.stf.getObjectValue(chb_F);
    url += "&SUBMIT_M=" + $c.stf.getObjectValue(chb_M);
    url += "&SUBMIT_A=" + $c.stf.getObjectValue(chb_A);
    url += "&SUBMIT_U=" + $c.stf.getObjectValue(chb_U);
    url += "&FORM_UPCLSS_CD=" + $c.stf.getObjectValue(cmb_UPCLSS);
    url += "&TP_CLSS_CD=" + $c.stf.getObjectValue(cmb_DISCLS_TP_CLSS);
    url += "&RSN_CLSS_CD=" + $c.stf.getObjectValue(cmb_DISCLS_RSN_CLSS);
    url += "&COM_TP_CD=" + $c.stf.getObjectValue(cmb_COMPANY_ATTRIBUTE);
    url += "&PAGENO=1";
    url += "&PAGESIZE=0"; // 전체.
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_07;
    dts_ForExcel.DataID = url;
    dts_ForExcel.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(grd_ForExcel, false);
    $c.stf.showObj(panel_mkt, false);
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_ISUR_CD_onclick = function() {
    //frame.CreateDialogFrame("DLG_ISUR_CD_","../listingcommon/ULDSTF92009.gfm", "회사선택", 10, 10, 350, 570, "window");
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_UPCLSS_OnSelChange = function() {
    scwin.fn_getClassByUpClass();
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    if (scwin.vCurrPageNo == 0) {
        scwin.vCurrPageNo = 1;
    }
    var vTotalCnt = dts_Grid.getCellData(1, "CNT");
    //alert("vTotalCnt=" + vTotalCnt);
    $c.stf.FillGridHeader2(scwin.pageNoCnt, $c.stf.getObjectValue(cmb_PerPage), vTotalCnt, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.cmb_PerPage_OnSelChange = function() {
    scwin.vCurrPageNo = 1;
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ToExcel();
};
scwin.dts_ForExcel_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid);
    $c.data.downloadGridViewExcel(grd_ForExcel, "공시건수현황", "c:\abs\test.xls", 16);
};
scwin.dts_ForExcel_OnLoadError = function() {
    $c.win.alert("엑셀 저장에 실패하였습니다.");
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == "COM_NM") {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "FORM_KOR_NM") {
        var vAcptNo = dts_Grid.getCellData(row, "ACPT_NO");
        $c.stf.fn_OpenDisclViewer(vAcptNo, "R");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.rdo_DISCLS_TYPE_OnClick = function() {
    var value = $c.stf.getObjectValue(rdo_DISCLS_TYPE);
    if (value == '1') {
        cmb_DISCLS_TP_CLSS.setDisabled(true);
        cmb_DISCLS_RSN_CLSS.setDisabled(true);
        cmb_DISCLS_RSN_CLSS.setSelectedIndex('0');
    } else {
        cmb_DISCLS_TP_CLSS.setDisabled(true);
        cmb_DISCLS_TP_CLSS.setSelectedIndex('0');
        cmb_DISCLS_RSN_CLSS.setDisabled(true);
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_HideDebugCtrls();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    scwin.fn_SetCode();
    scwin.initPage();
};
